class Solution:
    def numberOfWays(self, s: str) -> int:

        temp = []
        c0 = 0
        c1 = 0
        for char in s :
            if char == "0" :
                c0+=1
            else:
                c1+=1
            temp.append([c0,c1])

        total0 = c0
        total1 = c1


        count = 0
        for i in range(1, len(s)-1) :

            if s[i] == "0" :
                m1 = temp[i-1][1]
                m2 = total1 - temp[i][1]
                count += m1*m2

            else:
                m1 = temp[i-1][0]
                m2 = total0 - temp[i][0]
                count += m1*m2
        return count

class Solution(object):
    def countTexts(self, pressedKeys):
        dp = [1] + [0]*len(pressedKeys)
        mod = 10**9 + 7
        for i, n in enumerate(pressedKeys):
            dp[i+1] = dp[i]
            # check if is continous
            if i >= 1 and pressedKeys[i-1] == n:
                dp[i+1] += dp[i-1]
                dp[i+1] %= mod
                if i >= 2 and pressedKeys[i-2] == n:
                    dp[i+1] += dp[i-2]
                    dp[i+1] %= mod
                    # Special case for '7' and '9' that can have 4 characters combination
                    if i >= 3 and pressedKeys[i-3] == n and (n == "7" or n == "9"):
                        dp[i+1] += dp[i-3]
                        dp[i+1] %= mod
        return dp[-1]

class Solution:
    def minimumNumbers(self, num: int, k: int) -> int:
        if num == 0:
            return 0

        if k == 0:
            return 1 if num % 10 == 0 else -1

        for n in range(1, min(num // k, 10) + 1):
            if (num - n * k) % 10 == 0:
                return n

        return -1

